//! 🧪️ Native backing admissions retain each real allocation and original work receipt.
use semio_framework_value_native_decoding::*;
#[path="../../../🎟️work/🧪️tests/eff.rs"]
mod eff;
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u128){let work=u64::try_from(work).unwrap();assert!(p.fits(*bank));assert!(work<=1);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
fn close<T:retirement::RetireOwned>(value:T,bank:&mut RetainedCloneGrant,fuel:&mut u64){let mut owner=retirement::controlled::ControlledRetirement::new(value).map_err(|(error,_)|error).unwrap();for _ in 0..100000{if owner.terminal_is_empty(){return}let mut actual=None;let(p,heap)=eff::observed(RetainedCloneGrant{maximum_items:1,..*bank},*fuel,&mut actual,|effect|eff::settled(owner.step(effect)).result.unwrap().progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(bank,fuel,p,owner.last_turn_work());}panic!("native backing cleanup exhausted finite turns")}
struct WorkLoan(u64);
impl OriginalWorkRecipient for WorkLoan{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}fn recover_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}fn admits<'reply,'turn,'source>(&mut self,_:&mut (),quote:OriginalWorkQuote<'reply>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'reply>where 'source:'turn{quote.complete(Ok(observed.checked_add(additional).is_some_and(|n|n<=self.0.min(1))))}}
struct Construction{grant:RetainedCloneGrant,submitted:RetainedCloneProgress,refuse:bool}
impl OriginalConstructionRecipient for Construction{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}fn grant<'a,'turn,'source>(&mut self,_:&mut (),quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a>where 'source:'turn{quote.complete(Ok(self.grant))}fn accept<'a,'turn,'source>(&mut self,_:&mut (),receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a>where 'source:'turn{let grant=receipt.grant();let progress=receipt.progress();assert_eq!(grant,self.grant);assert!(progress.fits(grant));let result=self.submitted.checked_add(progress).and_then(|total|{self.submitted=total;if self.refuse{Err(ValueError::literal(ValueRefusalKind::Canceled,"construction post refused"))}else{Ok(())}});receipt.complete(result)}fn submitted<'turn,'source>(&self,_:&())->RetainedCloneProgress where 'source:'turn{self.submitted}}
struct Rig{work:OriginalWorkAuthority<WorkLoan>,authority:OriginalConstructionAuthority<Construction>}
fn rig(fuel:u64,grant:RetainedCloneGrant)->Rig{Rig{work:OriginalWorkAuthority::new(WorkLoan(fuel)),authority:OriginalConstructionAuthority::new(Construction{grant,submitted:Default::default(),refuse:false})}}
fn funded_turn(control:&mut NativeDecodeControl<'_>,rig:&mut Rig,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->NativeBackingTurn)->NativeBackingTurn{let Rig{work,authority}=rig;let turn=work.with_loan(&mut (),|work_loan|authority.with_loan(&mut (),|construction_loan|control.with_construction_recipient(construction_loan,|control|control.with_work_recipient(work_loan,|control|Ok::<_,ValueError>(operation(control))))).unwrap().unwrap()).unwrap();let progress=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};assert_eq!(authority.inspect(|recipient|recipient.submitted),progress);turn}
#[test]fn actual_native_backing_births_keep_null_denied_outputs_and_exact_cumulative_allocation(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(s["capacityBytes"].as_u64().unwrap()as usize,&mut callback);let mut frame=NativeReceivingEffect::default();let mut values=None;let denied=control.admit_vec::<u64>(&mut values,row["count"].as_u64().unwrap()as usize,RetainedCloneGrant{maximum_items:0,..bank},&mut frame);assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());assert!(values.is_none());let missing=control.admit_vec::<u64>(&mut values,row["count"].as_u64().unwrap()as usize,RetainedCloneGrant{maximum_items:1,..bank},&mut frame);assert_eq!(missing.work,0);assert_eq!(missing.result.unwrap_err().receiving.primary.unwrap().kind,ValueRefusalKind::UnsupportedOwner);assert!(values.is_none());let mut rig1=rig(fuel,bank);let mut attempts=0;let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||funded_turn(&mut control,&mut rig1,|control|{let(turn,count)=semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||control.admit_vec::<u64>(&mut values,row["count"].as_u64().unwrap()as usize,RetainedCloneGrant{maximum_items:1,..bank},&mut frame));attempts=count;turn}));assert_eq!(turn.work,u128::from(row["nullWork"].as_u64().unwrap()));fuel-=u64::try_from(turn.work).unwrap();assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert!(turn.result.is_err());assert!(values.is_none());assert_eq!(control.owned_bytes(),row["nullOwnedBytes"].as_u64().unwrap()as usize);
 let mut rig2=rig(fuel,bank);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||funded_turn(&mut control,&mut rig2,|control|control.admit_vec::<u64>(&mut values,row["count"].as_u64().unwrap()as usize,RetainedCloneGrant{maximum_items:1,..bank},&mut frame)));assert_eq!(turn.work,u128::from(row["birthWork"].as_u64().unwrap()));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.copied_bytes,std::mem::size_of::<Vec<u64>>());post(&mut bank,&mut fuel,p,turn.work);let first=control.owned_bytes();assert_eq!(first,row["nullOwnedBytes"].as_u64().unwrap()as usize+p.retained_capacity_bytes);assert_eq!(serde_json::to_value(values.as_ref().unwrap()).unwrap(),serde_json::json!([]));let mut text=None;let mut rig3=rig(fuel,bank);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||funded_turn(&mut control,&mut rig3,|control|control.admit_string(&mut text,row["text"].as_str().unwrap().len(),RetainedCloneGrant{maximum_items:1,..bank},&mut frame)));assert_eq!(turn.work,1);let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(control.owned_bytes(),first+p.retained_capacity_bytes);assert_eq!(p.copied_bytes,std::mem::size_of::<String>());post(&mut bank,&mut fuel,p,turn.work);assert_eq!(serde_json::to_value(text.as_ref().unwrap()).unwrap(),serde_json::json!(""));assert_eq!(control.actual_work(),u128::from(row["observedBirthWork"].as_u64().unwrap()));close(values.take().unwrap(),&mut bank,&mut fuel);close(text.take().unwrap(),&mut bank,&mut fuel);}

#[test]fn exact_backing_layout_handles_empty_zero_sized_and_ordinary_vectors(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();for case in row["layoutCases"].as_array().unwrap(){let count=case["count"].as_u64().unwrap()as usize;let expected=case["allocatedBytes"].as_u64().unwrap()as usize;match case["kind"].as_str().unwrap(){"zeroSized"=>{let mut marker=None;let(value,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||allocate_empty_vec::<()>(count,&mut marker).unwrap());assert_eq!(heap.0,expected);assert!(value.is_empty());drop(value)},"text"=>{let mut marker=None;let(value,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||allocate_empty_vec::<u8>(count,&mut marker).unwrap());assert_eq!(heap.0,expected);assert_eq!(value.capacity(),count);drop(value)},_=>{let mut marker=None;let(value,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||allocate_empty_vec::<u64>(count,&mut marker).unwrap());assert_eq!(heap.0,expected);assert_eq!(value.capacity(),count);drop(value)}}}}

#[test]fn refused_construction_post_retains_exact_vector_and_submitted_progress(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let stock=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut fuel=stock["fuel"].as_u64().unwrap();let mut observe=|_|true;let mut control=NativeDecodeControl::new(bank.maximum_capacity_bytes,&mut observe);let mut authority=OriginalConstructionAuthority::new(Construction{grant:bank,submitted:Default::default(),refuse:true});let mut work=OriginalWorkAuthority::new(WorkLoan(fuel));let mut output=None;let mut frame=NativeReceivingEffect::default();let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||work.with_loan(&mut (),|work_loan|authority.with_loan(&mut (),|construction_loan|control.with_construction_recipient(construction_loan,|control|control.with_work_recipient(work_loan,|control|Ok::<_,ValueError>(control.admit_vec::<u64>(&mut output,row["count"].as_u64().unwrap()as usize,bank,&mut frame))))).unwrap().unwrap()).unwrap());let error=turn.result.unwrap_err();assert_eq!(error.receiving.receipt_refusal.as_ref().unwrap().message.as_ref(),"construction post refused");assert_eq!(authority.inspect(|recipient|recipient.submitted),error.receiving.progress);assert_eq!(control.owned_bytes(),error.receiving.progress.retained_capacity_bytes);assert_eq!(heap,(error.receiving.progress.retained_capacity_bytes,0));assert!(output.is_some());post(&mut bank,&mut fuel,error.receiving.progress,turn.work);close(output.take().unwrap(),&mut bank,&mut fuel);close(error,&mut bank,&mut fuel);}

#[test]fn original_construction_quote_denial_precedes_allocation_and_work(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let stock=&row["stock"];let grant=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let fuel=stock["fuel"].as_u64().unwrap();let mut observe=|_|true;let mut control=NativeDecodeControl::new(grant.maximum_capacity_bytes,&mut observe);let mut authority=OriginalConstructionAuthority::new(Construction{grant:RetainedCloneGrant{maximum_capacity_bytes:0,..grant},submitted:Default::default(),refuse:false});let mut work=OriginalWorkAuthority::new(WorkLoan(fuel));let mut output=None;let mut frame=NativeReceivingEffect::default();let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||work.with_loan(&mut (),|work_loan|authority.with_loan(&mut (),|construction_loan|control.with_construction_recipient(construction_loan,|control|control.with_work_recipient(work_loan,|control|Ok::<_,ValueError>(control.admit_vec::<u64>(&mut output,row["count"].as_u64().unwrap()as usize,grant,&mut frame))))).unwrap().unwrap()).unwrap());assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(authority.inspect(|recipient|recipient.submitted),Default::default());assert!(output.is_none());assert_eq!(heap,(0,0));assert_eq!(control.owned_bytes(),0);assert_eq!(control.actual_work(),0);}

/// ⛽️ A held original work quote can only settle the actual retained child work.
#[test]
fn original_backing_work_rejects_false_actual_before_commit(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let row=&fixture["workSettlement"];let actual=row["actual"].as_u64().unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(4096,&mut callback);let grant=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};let mut authority=OriginalConstructionAuthority::new(Construction{grant,submitted:Default::default(),refuse:false});let mut work=OriginalWorkAuthority::new(WorkLoan(10));let mut frame:NativeReceivingEffect<ValueError>=NativeReceivingEffect::default();let turn=work.with_loan(&mut (),|work_loan|authority.with_loan(&mut (),|construction_loan|control.with_construction_recipient(construction_loan,|control|control.with_work_recipient(work_loan,|control|{frame.quote(control,RetirementDemand{depth:1,..Default::default()})?;assert_eq!(frame.prepare_work(control,actual)?,Some(true));frame.effect(control,|marker,_|{*marker=Some(0);RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:u128::from(actual)}})?;assert_eq!(row["zeroPhysicalIsWork"].as_bool(),Some(true));assert!(frame.cancel_unperformed_work(control).is_err());assert!(control.has_pending_work());assert_eq!(control.actual_work(),u128::from(actual));assert!(frame.settle_original_work(control)?);frame.finish_allocation(control)?;frame.receipt(control)?;frame.take(control)}))).unwrap().unwrap()).unwrap();assert_eq!(turn.work,u128::from(actual));assert!(turn.result.is_ok());assert_eq!(control.actual_work(),u128::from(actual));
}

#[test]fn empty_and_zero_sized_backing_have_no_allocation_event(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let stock=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut fuel=stock["fuel"].as_u64().unwrap();let mut events=0;let port=|_:NativeAllocationEvent|{events+=1;Ok(())};let mut authority=NativeAllocationAuthority::new(eff::Port(port));let mut observe=|_|true;authority.with_send_loan(&mut (),|loan|{let mut control=NativeDecodeControl::new_forwarded(bank.maximum_capacity_bytes,&mut observe,loan);let mut frame=NativeReceivingEffect::default();let mut empty=None;let turn=funded_turn(&mut control,&mut rig(fuel,bank),|control|control.admit_vec::<u64>(&mut empty,0,bank,&mut frame));let progress=turn.result.unwrap().progress();assert_eq!(turn.work,1);assert_eq!(progress.retained_capacity_bytes,0);post(&mut bank,&mut fuel,progress,turn.work);let mut zst=None;let turn=funded_turn(&mut control,&mut rig(fuel,bank),|control|control.admit_vec::<()>(&mut zst,7,bank,&mut frame));let progress=turn.result.unwrap().progress();assert_eq!(turn.work,1);assert_eq!(progress.retained_capacity_bytes,0);post(&mut bank,&mut fuel,progress,turn.work);assert_eq!(control.owned_bytes(),0);drop(control);close(empty.take().unwrap(),&mut bank,&mut fuel);close(zst.take().unwrap(),&mut bank,&mut fuel);}).unwrap();assert!(authority.into_port().is_ok());assert_eq!(events,0);}
